</div><script>(function(){'use strict';var BASE='<?= CUtil::JSEscape($basePath) ?>',SITE=<?= $siteId ?>,ADMIN=<?= $isBitrixAdmin?'true':'false' ?>,API=BASE+'/api.php';function sid(){return window.BX&&BX.bitrix_sessid?BX.bitrix_sessid():'<?= CUtil::JSEscape(bitrix_sessid()) ?>'}async function api(a,d){var r=await fetch(API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(Object.assign({action:a,sessid:sid()},d||{}))}),t=await r.text(),j;try{j=JSON.parse(t)}catch(e){throw{error:'BAD_JSON_RESPONSE',text:t}}if(!j||j.ok!==true)throw j||{error:'UNKNOWN_ERROR'};return j}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}function message(t,e){var n=document.getElementById('message');n.style.display='block';n.style.color=e?'#991b1b':'#166534';n.textContent=t}async function load(){var r=await api('job.list',{siteId:SITE,status:document.getElementById('statusFilter').value,jobType:document.getElementById('typeFilter').value,limit:200}),rows=r.items||[],n=document.getElementById('rows');n.innerHTML=rows.length?rows.map(function(x){return '<tr><td>#'+Number(x.id)+'</td><td>'+esc(x.jobType)+'</td><td><span class="job-status '+esc(x.status)+'">'+esc(x.status)+'</span></td><td>'+Number(x.attempts)+' / '+Number(x.maxAttempts)+'</td><td>'+esc(x.availableAt)+'</td><td>'+esc(x.lastErrorCode||'—')+'</td><td><button class="sb-btn sb-btn-light sb-btn-small open" data-id="'+Number(x.id)+'">Открыть</button></td></tr>'}).join(''):'<tr><td colspan="7">Заданий нет</td></tr>'}async function openJob(id){var r=await api('job.get',{jobId:id}),j=r.job||{};document.getElementById('detailMeta').textContent='Задание #'+id+' · '+(j.jobType||'');document.getElementById('detail').textContent=JSON.stringify(r,null,2);var a='';if(['dead','cancelled','retry'].indexOf(j.status)>=0)a+='<button class="sb-btn sb-btn-light retry" data-id="'+id+'">Повторить</button>';if(['pending','retry'].indexOf(j.status)>=0)a+='<button class="sb-btn sb-btn-light cancel" data-id="'+id+'">Отменить</button>';document.getElementById('detailActions').innerHTML=a}document.addEventListener('click',function(e){var b=e.target.closest('.open');if(b)openJob(Number(b.dataset.id)).catch(function(x){message(x.error||'Ошибка',true)});b=e.target.closest('.retry');if(b)api('job.retry',{jobId:Number(b.dataset.id)}).then(function(){message('Задание возвращено в очередь',false);return load()}).catch(function(x){message(x.error||'Ошибка',true)});b=e.target.closest('.cancel');if(b)api('job.cancel',{jobId:Number(b.dataset.id)}).then(function(){message('Задание отменено',false);return load()}).catch(function(x){message(x.error||'Ошибка',true)})});document.getElementById('reloadBtn').onclick=load;document.getElementById('applyBtn').onclick=load;if(ADMIN)document.getElementById('runBtn').onclick=function(){var b=this;b.disabled=true;api('job.run',{limit:20}).then(function(r){message('Worker завершён: '+JSON.stringify(r.result||{}),false);return load()}).catch(function(x){message(x.error||'Ошибка',true)}).finally(function(){b.disabled=false})};load().catch(function(x){message(x.error||'Ошибка загрузки',true)});})();</script></body></html>
